def compute(vars):
    alpharetta_sq_ft = vars["v1"]
    jersey_city_sq_ft = vars["v2"]

    if jersey_city_sq_ft == 0:
        return None

    ratio = alpharetta_sq_ft / jersey_city_sq_ft
    return {
        "value": ratio,
        "trace": {
            "alpharetta_sq_ft": alpharetta_sq_ft,
            "jersey_city_sq_ft": jersey_city_sq_ft,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
